\set ON_ERROR_STOP on
begin;
-- MU GKZ: corrales de Arena abiertos, también las puertas de abajo de los dos de arriba (16-17,86 y 29-30,86).
update config."GameMapDefinition" set "TerrainData" = decode('', 'base64') where "Number" = 6;
select "Number", length("TerrainData") from config."GameMapDefinition" where "Number" = 6;
commit;
